 console.log("STATE",r.state,"DURABLE",r.durable?.job_status,"MODEL_CALLS",JSON.stringify([...latest.values()].map(p=>({role:p.role,phase:p.phase,elapsed_ms:p.elapsed_ms,failure_code:p.failure_code,invocation_id:p.invocation_id,telemetry:p.telemetry}))));
